class Solution:
    def countOddStretches(self, tickets: List[int], k: int) -> int:
        n, total = len(tickets), 0
        for i in range(n):
            odd = 0
            for j in range(i, n):
                odd += tickets[j] & 1
                if odd > k:
                    break
                if odd == k:
                    total += 1
        return total

