class Solution:
    def countOddStretches(self, tickets: List[int], k: int) -> int:
        seen = [0] * (len(tickets) + 1)
        seen[0] = 1
        p = total = 0
        for v in tickets:
            p += v & 1
            if p >= k:
                total += seen[p - k]
            seen[p] += 1
        return total

