class Solution {
    private long atMost(int[] tickets, int limit) {
        int left = 0, odd = 0;
        long total = 0;
        for (int i = 0; i < tickets.length; i++) {
            odd += tickets[i] & 1;
            while (odd > limit) odd -= tickets[left++] & 1;
            total += i - left + 1;
        }
        return total;
    }

    public long countOddStretches(int[] tickets, int k) {
        return atMost(tickets, k) - atMost(tickets, k - 1);
    }
}

