static long long at_most(const int* tickets, int n, int limit) {
    int left = 0, odd = 0;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        odd += tickets[i] & 1;
        while (odd > limit) odd -= tickets[left++] & 1;
        total += i - left + 1;
    }
    return total;
}

long long countOddStretches(int* tickets, int ticketsSize, int k) {
    return at_most(tickets, ticketsSize, k) - at_most(tickets, ticketsSize, k - 1);
}
